new_backtrack <- function(pattern, text, full) {
    record(engine = "backtrack", program = pattern$program, flags = pattern$flags,
        groups = pattern$groups, text = text, full = full, steps = 0L)
}
execute_backtrack <- function(vm, initial_instruction, initial_position, initial_captures, partial) {
    stack <- list(list(pc = initial_instruction, position = initial_position, captures = initial_captures, visited = rep(FALSE, length(vm$program))))
    while (length(stack)) {
        state <- stack[[length(stack)]]
        stack[[length(stack)]] <- NULL
        pc <- state$pc
        position <- state$position
        captures <- state$captures
        visited <- state$visited
        repeat {
            vm$steps <- vm$steps + 1L
            if (vm$steps > 200000L) stop(structure(list(message = "TOO_MANY_STEPS"), class = c("too_many_steps", "error", "condition")))
            instruction <- vm$program[[pc + 1L]]
            op <- instruction$op
            if (op %in% c("CHAR", "ANY", "CLASS")) {
                accepts <- if (op == "CHAR") {
                    test_char(vm$text, position, instruction$character, vm$flags)
                } else if (op == "ANY") {
                    test_any(vm$text, position, vm$flags)
                } else test_class(vm$text, position, instruction$codes, instruction$negated, vm$flags)
                if (!accepts) break
                position <- position + 1L
                pc <- pc + 1L
                visited <- rep(FALSE, length(vm$program))
            } else if (op == "SPLIT") {
                if (visited[pc + 1L]) break
                visited[pc + 1L] <- TRUE
                stack[[length(stack) + 1L]] <- list(pc = instruction$y, position = position, captures = captures, visited = visited)
                pc <- instruction$x
            } else if (op == "JMP") {
                pc <- instruction$x
            } else if (op == "SAVE") {
                captures[instruction$slot + 1L] <- position
                pc <- pc + 1L
            } else if (op == "ASSERT") {
                if (!assertion(instruction$kind, vm$text, position, vm$flags)) break
                pc <- pc + 1L
            } else if (op == "BACKREF") {
                beginning <- captures[2L * instruction$group + 1L]
                finish <- captures[2L * instruction$group + 2L]
                if (beginning < 0L || finish < 0L || beginning > finish) break
                distance <- finish - beginning
                if (position + distance > nchar(vm$text)) break
                accepts <- TRUE
                for (offset in seq_len(distance) - 1L) {
                    if (!characters_equal(substr(vm$text, position + offset + 1L, position + offset + 1L),
                        substr(vm$text, beginning + offset + 1L, beginning + offset + 1L), vm$flags)) {
                        accepts <- FALSE
                        break
                    }
                }
                if (!accepts) break
                position <- position + distance
                pc <- pc + 1L
                if (distance > 0L) visited <- rep(FALSE, length(vm$program))
            } else if (op == "LOOK") {
                result <- execute_backtrack(vm, pc + 1L, position, captures, TRUE)
                if (instruction$kind == "NOT") {
                    if (!is.null(result)) break
                } else {
                    if (is.null(result)) break
                    captures <- result$captures
                    if (instruction$kind == "ATOMIC") {
                        if (result$position > position) visited <- rep(FALSE, length(vm$program))
                        position <- result$position
                    }
                }
                pc <- instruction$x
            } else if (partial || !vm$full || position == nchar(vm$text)) {
                return(list(captures = captures, position = position))
            } else break
        }
    }
    NULL
}
search_backtrack <- function(vm, start) {
    positions <- if (vm$full) 0L else seq.int(start, nchar(vm$text))
    for (beginning in positions) {
        found <- execute_backtrack(vm, 0L, beginning, rep.int(-1L, 2L * (vm$groups + 1L)), FALSE)
        if (!is.null(found)) return(found$captures)
    }
    NULL
}

ASCII <- 0L:127L
DIGITS <- 48L:57L
LOWER <- 97L:122L
UPPER <- 65L:90L
WORD <- sort(unique(c(DIGITS, LOWER, UPPER, 95L)))
SPACE <- c(9L, 10L, 11L, 12L, 13L, 32L)
STANDARD <- list(d = DIGITS, w = WORD, s = SPACE)

has_flag <- function(flags, flag) flag %in% strsplit(flags, "", fixed = TRUE)[[1L]]
is_letter <- function(character) {
    character != "" && utf8ToInt(character) %in% c(LOWER, UPPER)
}
is_digit <- function(character) {
    character != "" && utf8ToInt(character) %in% DIGITS
}
switched_code <- function(code) {
    if (code %in% LOWER) return(code - 32L)
    if (code %in% UPPER) return(code + 32L)
    code
}
escaped_set <- function(character) {
    code <- utf8ToInt(character)
    lower <- intToUtf8(if (code %in% UPPER) code + 32L else code)
    base <- STANDARD[[lower]]
    if (code %in% UPPER) setdiff(ASCII, base) else base
}
characters_equal <- function(a, b, flags) {
    a == b || (has_flag(flags, "i") && is_letter(a) && switched_code(utf8ToInt(a)) == utf8ToInt(b))
}
test_char <- function(text, position, expected, flags) {
    position < nchar(text) && characters_equal(substr(text, position + 1L, position + 1L), expected, flags)
}
test_any <- function(text, position, flags) {
    position < nchar(text) && (has_flag(flags, "s") || substr(text, position + 1L, position + 1L) != "\n")
}
code_matches_class <- function(code, codes, negated, flags) {
    present <- code %in% codes || (has_flag(flags, "i") && code %in% c(LOWER, UPPER) && switched_code(code) %in% codes)
    present != negated
}
test_class <- function(text, position, codes, negated, flags) {
    position < nchar(text) && code_matches_class(utf8ToInt(substr(text, position + 1L, position + 1L)), codes, negated, flags)
}
is_word_at <- function(text, position) {
    position >= 0L && position < nchar(text) && utf8ToInt(substr(text, position + 1L, position + 1L)) %in% WORD
}
assertion <- function(kind, text, position, flags) {
    if (kind == "BOL") return(position == 0L || (has_flag(flags, "m") && substr(text, position, position) == "\n"))
    if (kind == "EOL") return(position == nchar(text) || (has_flag(flags, "m") && substr(text, position + 1L, position + 1L) == "\n"))
    edge <- is_word_at(text, position - 1L) != is_word_at(text, position)
    if (kind == "WORD") edge else !edge
}

character_display <- function(code) {
    if (code >= 33L && code <= 126L && !code %in% c(92L, 93L, 94L, 45L)) return(intToUtf8(code))
    paste0("\\x", sprintf("%02X", code))
}
set_notation <- function(codes, negated = FALSE) {
    codes <- sort(unique(codes))
    pieces <- character()
    index <- 1L
    while (index <= length(codes)) {
        last <- index
        while (last < length(codes) && codes[last + 1L] == codes[last] + 1L) last <- last + 1L
        a <- character_display(codes[index])
        b <- character_display(codes[last])
        run <- last - index + 1L
        pieces <- c(pieces, if (run == 1L) a else if (run == 2L) paste0(a, b) else paste0(a, "-", b))
        index <- last + 1L
    }
    paste0("[", if (negated) "^" else "", paste0(pieces, collapse = ""), "]")
}
instruction_notation <- function(entry) {
    switch(entry$op,
        CHAR = paste("CHAR", character_display(utf8ToInt(entry$character))),
        CLASS = paste("CLASS", set_notation(entry$codes, entry$negated)),
        SPLIT = paste0("SPLIT ", entry$x, ", ", entry$y),
        JMP = paste("JMP", entry$x),
        SAVE = paste("SAVE", entry$slot),
        ASSERT = paste("ASSERT", entry$kind),
        BACKREF = paste("BACKREF", entry$group),
        LOOK = paste("LOOK", entry$kind, entry$x),
        entry$op)
}
quoted <- function(text) {
    characters <- strsplit(text, "", fixed = TRUE)[[1L]]
    encoded <- vapply(characters, function(character) {
        if (character == "\\") "\\\\" else if (character == "\"") "\\\"" else if (character == "\n") "\\n" else if (character == "\t") "\\t" else character
    }, character(1L))
    paste0("\"", paste0(encoded, collapse = ""), "\"")
}

